const r = await api.get("/customers", {});
const items = r.items || [];
const nov = items.filter(c => {
  const d = String(c.birth_date || "");
  const m = d.match(/^\d{4}[-./](\d{1,2})/) || d.match(/^(\d{1,2})[-./]\d{1,2}$/);
  return m && parseInt(m[1], 10) === 11;
});
const unparsed = items.filter(c => !/^\d{4}[-./]\d{1,2}/.test(String(c.birth_date || ""))).length;
return { total_in_items: items.length, reported_count: r.count, nov_count: nov.length, unparsed_birth_dates: unparsed, sample_birth_dates: items.slice(0,5).map(c => c.birth_date) };

